import sys

def can_form_matrix(matrix, n):
    for i in range(n):
        for j in range(n):
            if matrix[i][j] == '1':
                if not (all(matrix[i][k] == '0' for k in range(j)) or all(matrix[k][j] == '0' for k in range(i))):
                    return False
    return True

input = sys.stdin.read().split()
index = 0
results = []
t = int(input[index])
index += 1
for _ in range(t):
    n = int(input[index])
    index += 1
    matrix = input[index:index + n]
    index += n
    if can_form_matrix(matrix, n):
        results.append('YES')
    else:
        results.append('NO')
print('\n'.join(results))
